const run = $input.first().json;
const text = $('Extract CSV as Text').first().json.data;

if (typeof text !== 'string' || text.length === 0) {
  throw new Error('RBA source text is missing');
}

const lines = text.split(/\r?\n/);

const headerIndex = lines.findIndex((line) =>
  line.replace(/^\uFEFF/, '').startsWith('Series ID,')
);

if (headerIndex === -1) {
  throw new Error('Could not find the RBA Series ID header');
}

const cleanedCsv = lines
  .slice(headerIndex)
  .join('\n')
  .trim();

return [{
  json: {
    run_id: Number(run.run_id),
    source: run.source,
    source_fingerprint: run.source_fingerprint,
    cleanedCsv
  }
}];

const input = $input.first().json;
const text = input.cleanedCsv;

function parseCsv(csvText) {
  const normalized = csvText
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < normalized.length; i++) {
    const ch = normalized[i];

    if (inQuotes) {
      if (ch === '"') {
        if (normalized[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }

      continue;
    }

    if (ch === '"') {
      inQuotes = true;

    } else if (ch === ',') {
      row.push(field);
      field = '';

    } else if (ch === '\n') {
      row.push(field);
      rows.push(row);

      row = [];
      field = '';

    } else {
      field += ch;
    }
  }

  if (inQuotes) {
    throw new Error(
      'Malformed CSV: unclosed quoted field'
    );
  }

  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}


const matrix = parseCsv(text)
  .filter((row) =>
    row.some(
      (value) =>
        String(value).trim() !== ''
    )
  );


if (matrix.length < 2) {
  throw new Error(
    'CSV contains a header but no data rows'
  );
}


const headers = matrix[0].map((header) =>
  String(header)
    .replace(/^\uFEFF/, '')
    .trim()
);


if (headers[0] !== 'Series ID') {
  throw new Error(
    `Unexpected first header: ${headers[0]}`
  );
}


const seenHeaders = new Set();

for (const header of headers) {

  if (header === '') {
    throw new Error(
      'Malformed CSV: blank header detected'
    );
  }

  if (seenHeaders.has(header)) {
    throw new Error(
      `Malformed CSV: duplicate header "${header}"`
    );
  }

  seenHeaders.add(header);
}


const output = [];


for (
  let dataIndex = 1;
  dataIndex < matrix.length;
  dataIndex++
) {

  const values = matrix[dataIndex];

  if (values.length !== headers.length) {
    throw new Error(
      `Malformed CSV at data row ${dataIndex}: ` +
      `expected ${headers.length} fields, ` +
      `got ${values.length}`
    );
  }


  const obj = {
    run_id: input.run_id,
    source: input.source,
    source_row_no: dataIndex
  };


  headers.forEach((header, i) => {
    obj[header] = values[i];
  });


  output.push({
    json: obj
  });
}


return output;

const output = [];

const reservedKeys = new Set([
  'run_id',
  'source',
  'source_row_no',
  'Series ID'
]);

for (const item of $input.all()) {
  const row = item.json;

  const rawRateDate =
    row['Series ID'] === undefined ||
    row['Series ID'] === null
      ? null
      : String(row['Series ID']);

  for (const [seriesId, value] of Object.entries(row)) {

    if (reservedKeys.has(seriesId)) {
      continue;
    }

    output.push({
      json: {
        run_id: Number(row.run_id),
        source_row_no: Number(row.source_row_no),
        raw_rate_date: rawRateDate,
        series_id: String(seriesId),

        raw_rate:
          value === undefined ||
          value === null
            ? null
            : String(value),

        source: row.source
      }
    });
  }
}

return output;

const items = $input.all();

if (items.length === 0) {
  throw new Error('No normalized records received');
}

const runId = Number(items[0].json.run_id);

for (const item of items) {
  if (Number(item.json.run_id) !== runId) {
    throw new Error(
      'Mixed run_id values detected in one staging batch'
    );
  }
}

const records = items.map((item) => ({
  source_row_no: Number(
    item.json.source_row_no
  ),

  raw_rate_date:
    item.json.raw_rate_date,

  series_id:
    item.json.series_id,

  raw_rate:
    item.json.raw_rate,

  source:
    item.json.source
}));

return [{
  json: {
    run_id: runId,
    normalized_record_count:
      records.length,
    records
  }
}];
